steps <- numeric()
messages <- character()
handler <- make_progression_handler("rec", reporter = list(
  update = function(config, state, progression, ...) {
    steps <<- c(steps, state$step)
    messages <<- c(messages, state$message)
  }
), enable = TRUE, target = "file", interval = 0)
withCallingHandlers({
  signalCondition(progression(type = "initiate", steps = 4, auto_finish = TRUE, progressor_uuid = "p", progression_index = 1L))
  for (k in 1:4) {
    signalCondition(progression(type = "update", amount = 1, message = letters[k], progressor_uuid = "p", progression_index = k + 1L))
  }
}, progression = handler)
cat(paste(steps, collapse = " "), "\n", sep = "")
cat(paste(messages, collapse = " "), "\n", sep = "")
